/* Тело «Длина до закрытия»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_dlina_do_zakrytiya_body(fl_ctx *ctx, fl_value simvoly, fl_value sedeno, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(simvoly)) {
      *result = fl_number(0.0);
      return FL_OK;
    } else if (fl_chain_cons(simvoly)) {
      const fl_value golova = fl_chain_head(simvoly); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(simvoly); /* хвост «хвост» */
      bool fl_t554 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(golova, kompilyator_flang_text_256)), &fl_t554, error));
      fl_value fl_t555 = fl_nothing();
      if (fl_t554) {
        fl_value fl_t556 = fl_nothing();
        FL_TRY(kompilyator_flang_pervyy_vperedi(ctx, hvost, &fl_t556, error));
        fl_t555 = fl_flag(fl_equal(fl_t556, kompilyator_flang_text_206));
      } else {
        fl_t555 = fl_flag(false);
      }
      bool fl_t557 = false;
      FL_TRY(fl_cond(ctx, fl_t555, &fl_t557, error));
      if (fl_t557) {
        if (sedeno.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "add", sedeno, fl_number(2.0), error));
        *result = fl_number(sedeno.as.number + 2.0);
        return FL_OK;
      } else {
        if (sedeno.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "add", sedeno, fl_number(1.0), error));
        const fl_value fl_t558 = fl_number(sedeno.as.number + 1.0);
        simvoly = hvost;
        sedeno = fl_t558;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Длина до закрытия", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, simvoly, error);
    }
  }
}

/*
 * Функция flang «Длина до закрытия».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param simvoly — «символы»: список: строка
 * @param sedeno — «съедено»: число
 * @return значение: число
 */
fl_status kompilyator_flang_dlina_do_zakrytiya(fl_ctx *ctx, fl_value simvoly, fl_value sedeno, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Длина до закрытия", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_dlina_do_zakrytiya_body(ctx, simvoly, sedeno, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

