/*
 * Функция flang «Нет тела».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param telo — «тело»: «Может быть узел при разборе»
 * @return значение
 */
fl_status kompilyator_flang_net_tela(fl_ctx *ctx, fl_value telo, fl_value *result, fl_error *error) {
  if (fl_variant_is(telo, "Есть узел при разборе")) {
    fl_value vnutri = fl_nothing();
    FL_TRY(fl_variant_field(ctx, telo, "узел", &vnutri, error)); /* «узел» */
    (void)vnutri;
    *result = fl_flag(false);
    return FL_OK;
  } else if (fl_variant_is(telo, "Нет узла при разборе")) {
    *result = fl_flag(true);
    return FL_OK;
  } else {
    return fl_match_fail(ctx, telo, error);
  }
}

