      fl_value fl_t10250 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t10248, gotovye, &fl_t10250, error));
      arnosti = hvost;
      zanyatye = fl_t10247;
      gotovye = fl_t10250;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Назвать диспетчеры", error));
